namespace YourNamespace
{
    public class SalesReportModel : PageModel
    {
        private readonly IConfiguration _configuration;
        private readonly DbDataSource _dbDataSource;

        public SalesReportModel(IConfiguration configuration, DbDataSource dbDataSource)
        {
            _configuration = configuration;
            _dbDataSource = dbDataSource;
        }

        public async Task<IActionResult> OnGetAsync(int year, CancellationToken cancellationToken)
        {
            if (Session["Role"] != "Admin")
            {
                return Redirect("login.asp");
            }

            var reportYear = year;

            var connectionString = _configuration.GetConnectionString("SalesDb");

            using (var connection = new SqlConnection(connectionString))
            {
                await connection.OpenAsync(cancellationToken);

                var command = new SqlCommand("SELECT Region, SUM(Amount) AS Total FROM Sales WHERE YEAR(SaleDate) = @Year GROUP BY Region", connection);
                command.Parameters.AddWithValue("@Year", reportYear);

                using (var reader = await command.ExecuteReaderAsync(cancellationToken))
                {
                    using (var fso = new System.IO.FileStream(
                        Path.Combine(_env.ContentRootPath, "reports", $"sales-{reportYear}.csv"),
                        System.IO.FileMode.Create,
                        System.IO.FileAccess.Write,
                        System.IO.FileShare.None,
                        System.IO.FileOptions.Asynchronous,
                        cancellationToken
                    ))
                    using (var writer = new System.IO.StreamWriter(fso, cancellationToken: cancellationToken))
                    {
                        writer.WriteLine("Region,Total");

                        while (await reader.ReadAsync(cancellationToken))
                        {
                            writer.WriteLine(reader["Region"] + "," + reader["Total"]);
                        }
                    }
                }
            }

            return Content("Report for " + reportYear + " saved.");
        }
    }
}

