using System.Threading;
using System.Threading.Tasks;

namespace YourNamespace
{
    public class SalesReportModel : PageModel
    {
        private readonly IConfiguration _configuration;

        public SalesReportModel(IConfiguration configuration)
        {
            _configuration = configuration;
        }

        public async Task<IActionResult> OnGetAsync(CancellationToken cancellationToken)
        {
            if (Session["Role"] != "Admin")
            {
                return Redirect("login.asp");
            }

            var reportYear = CInt(Request.QueryString("year"));

            var connectionString = _configuration.GetConnectionString("SalesDb");

            using (var conn = new SqlConnection(connectionString))
            {
                conn.Open();

                var cmd = new SqlCommand("SELECT Region, SUM(Amount) AS Total FROM Sales WHERE YEAR(SaleDate) = @reportYear GROUP BY Region", conn);
                cmd.Parameters.AddWithValue("@reportYear", reportYear);

                using (var reader = await cmd.ExecuteReaderAsync(cancellationToken))
                {
                    using (var fso = new System.IO.FileStream(Path.Combine(_env.ContentRootPath, "reports", $"sales-{reportYear}.csv"), System.IO.FileMode.Create, System.IO.FileAccess.Write))
                    using (var csv = new System.IO.StreamWriter(fso))
                    {
                        csv.WriteLine("Region,Total");

                        while (await reader.ReadAsync(cancellationToken))
                        {
                            csv.WriteLine(reader["Region"] + "," + reader["Total"]);
                        }
                    }
                }
            }

            return Content("Report for " + reportYear + " saved.");
        }
    }
}

